void setZipCode(String zipCode) {
    if (!zipCode.matches("\\d{2}-\\d{3}")) throw new IllegalArgumentException("Zly format kodu pocztowego");
    this.zipCode = zipCode;
}

@Embeddable class Money {
    private final double amount; private final String currency;
    protected Money() { amount=0; currency=null; } // wymagany przez Hibernate
    public Money(double a, String c) { amount=a; currency=c; }
}
