@Converter class ZipCodeConverter implements AttributeConverter<String,String> {
    public String convertToDatabaseColumn(String s) { return s.replace("-", ""); }
    public String convertToEntityAttribute(String s) { return s.substring(0,2) + "-" + s.substring(2); }
}

